// 1. Recuperamos las facturas obtenidas de SQL Server
const facturas = $('Microsoft SQL').all().map(item => item.json);

// 2. Recuperamos el historial de Google Sheets
const historial = $input.all()
  .map(item => item.json)
  .filter(row => row.ID_Cartera);

// 3. Identificamos las facturas que YA tienen
// un aviso preventivo enviado.

const avisosEnviados = new Set(
  historial
    .filter(row =>
      String(row.Tipo_Aviso ?? '').trim().toLowerCase() === 'preventivo' &&
      String(row.Estado ?? '').trim().toLowerCase() === 'enviado'
    )
    .map(row => String(row.ID_Cartera).trim())
);

// 4. Excluimos las facturas que ya han sido avisadas
const pendientes = facturas.filter(factura =>
  !avisosEnviados.has(String(factura.ClaveCartera).trim())
);

// 5. Devolvemos todos los campos originales de SQL
return pendientes.map(factura => ({
  json: factura
}));

const facturas = $input.all().map(item => item.json);

const grupos = {};

for (const f of facturas) {

  // Agrupamos por empresa y cliente
  const clave = `${f.Empresa}-${f.Cliente}`;

  if (!grupos[clave]) {
    grupos[clave] = {
      Empresa: f.Empresa,
      Cliente: f.Cliente,
      Emails: new Set(),
      Facturas: [],
      Total: 0
    };
  }

  // Separamos los correos por ; o ,
  const emails = String(f.EmailDestino || '')
    .split(/[;,]/)
    .map(email => email.trim())
    .filter(email => email.length > 0);

  emails.forEach(email => grupos[clave].Emails.add(email));

  // Conservamos todos los datos de la factura
  grupos[clave].Facturas.push(f);

  grupos[clave].Total += Number(f.Importe) || 0;
}

// Generamos una salida por cliente
return Object.values(grupos).map(g => ({
  json: {
    Empresa: g.Empresa,
    Cliente: g.Cliente,
    EmailDestino: [...g.Emails].join(','),
    NumeroFacturas: g.Facturas.length,
    Facturas: g.Facturas,
    Total: Math.round(g.Total * 100) / 100
  }
}));

const grupos = $input.all();

return grupos.map(item => {

  const g = item.json;

  // Formato español para importes
  const euros = valor =>
    Number(valor).toLocaleString('es-ES', {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2
    }) + ' €';

  // Formato de fechas
  const fecha = valor => {
    if (!valor) return '';
    const s = String(valor).substring(0, 10);
    const [a, m, d] = s.split('-');
    return `${d}/${m}/${a}`;
  };

  // Filas de las facturas
  const filas = g.Facturas.map(f => `
    <tr>
      <td style="padding:8px;border:1px solid #ddd;">
        ${f.Factura}
      </td>
      <td style="padding:8px;border:1px solid #ddd;">
        ${fecha(f.FechaVencimiento)}
      </td>
      <td style="padding:8px;border:1px solid #ddd;text-align:right;">
        ${euros(f.Importe)}
      </td>
    </tr>
  `).join('');

  const html = `
    <p>Estimado/a cliente:</p>

    <p>
      Nos ponemos en contacto con usted para recordarle
      que las siguientes facturas tienen previsto su
      vencimiento próximamente:
    </p>

    <table style="border-collapse:collapse;width:100%;">
      <thead>
        <tr style="background-color:#eeeeee;">
          <th style="padding:8px;border:1px solid #ddd;">Factura</th>
          <th style="padding:8px;border:1px solid #ddd;">Vencimiento</th>
          <th style="padding:8px;border:1px solid #ddd;">Importe</th>
        </tr>
      </thead>
      <tbody>
        ${filas}
        <tr>
          <td colspan="2" style="padding:8px;text-align:right;">
            <strong>Total pendiente:</strong>
          </td>
          <td style="padding:8px;text-align:right;">
            <strong>${euros(g.Total)}</strong>
          </td>
        </tr>
      </tbody>
    </table>

    <p>
      Le agradeceríamos que tuviera en cuenta estos
      vencimientos para proceder a su pago en las fechas acordadas.
    </p>

    <p>
      Si ya ha gestionado el pago, puede hacer caso
      omiso de esta comunicación.
    </p>

    <p>
      Para cualquier consulta o aclaración,
      puede responder directamente a este correo.
    </p>

    <p>Muchas gracias por su colaboración.</p>

    <p>
  Un cordial saludo,<br><br>

  <strong>Departamento de Administración y Cobros</strong><br>
  <strong>DIANIA LOGISTICS, S.L.</strong><br>
  <a href="mailto:cobros@diania.es"
     style="color:#24804b;text-decoration:none;">
    cobros@diania.es
  </a>
</p>
  `;

  return {
    json: {
      ...g,
    Asunto: `Recordatorio de vencimiento de facturas - ${g.Facturas[0].NombreCliente} - Diania`,
      CuerpoHTML: html
    }
  };

});

//
// LOG DE ENVÍOS - 
// Genera una fila por factura de cada correo enviado.
//

// Resultados devueltos por Outlook
const resultados = $input.all();

// Grupos originales preparados para el envío
const grupos = $('Preparar correo preventivo').all();

const registros = [];

// Recorremos únicamente los correos procesados
for (let i = 0; i < resultados.length; i++) {

  const grupo = grupos[i]?.json;

  if (!grupo) {
    throw new Error(
      `No se encuentra el grupo correspondiente al envío ${i + 1}`
    );
  }

  const fechaEnvio = new Date().toISOString();

  // Una fila por factura del cliente
  for (const f of grupo.Facturas) {

    registros.push({
      json: {
        ID_Cartera: f.ClaveCartera,

        // Identificador único por factura y tipo de aviso
        ClaveEnvio: `${f.ClaveCartera}-Preventivo`,

        Empresa: f.Empresa,
        Cliente: f.Cliente,
        NombreCliente: f.NombreCliente,
        Factura: f.Factura,
        Tipo_Aviso: 'Preventivo',
        Fecha_Vencimiento: f.FechaVencimiento,
        Importe: f.Importe,
        Fecha_Envio: fechaEnvio,
        EmailDestino: 'etercero@diania.es',
        Estado: 'Enviado',
        Error: ''
      }
    });

  }
}

return registros;
